-- Attachment id (Firearms.Attachments) -> its model and the point it goes on. Its own origin is the start of the
-- threads (Muzzle), under the mount (Optic) or its top (Under).
GunParts.Accessories = {
	Suppressor = { Asset = 91150103074678, At = "Muzzle" },
	Compensator = { Asset = 115304335259984, At = "Muzzle" },
	PSO = { Asset = 116861313972870, At = "Optic" },
	Colt3x = { Asset = 72916934157658, At = "Optic" },
	Foregrip = { Asset = 74324230298414, At = "Under" },
}

-- Attachment id in the Barrel slot -> the barrel option
GunParts.BarrelOf = { BarrelShort = "Short", BarrelLong = "Long" }

local function idOf(attachments, slot)
	local a = attachments and attachments[slot]
	return if type(a) == "table" then a.Id else a
end

function GunParts.Barrel(gunId, attachments)
	local gun = GunParts.Guns[gunId]
	local option = GunParts.BarrelOf[idOf(attachments, "Barrel") or ""] or "Standard"
	return gun and (gun.Barrels[option] or gun.Barrels.Standard), option
end

-- One string per distinct build, so a held gun is only rebuilt when it changes.
function GunParts.Key(gunId, attachments)
	local _, option = GunParts.Barrel(gunId, attachments)
	return table.concat({ option or "", idOf(attachments, "Muzzle") or "", idOf(attachments, "Optic") or "", idOf(attachments, "Grip") or "" }, "|")
end

-- The models a build is made of: { { Name, Asset, At = Vector3 or nil (the gun's origin) }, ... }, or nil.
function GunParts.Pieces(gunId, attachments)
	local gun = GunParts.Guns[gunId]
	if not gun then
		return nil
	end
	local barrel = GunParts.Barrel(gunId, attachments)
	local pieces = { { Name = "Receiver", Asset = gun.Receiver }, { Name = "Barrel", Asset = barrel.Asset } }
	local points = { Muzzle = barrel.Muzzle, Under = barrel.Under, Optic = gun.Optic }
	local device = GunParts.Accessories[idOf(attachments, "Muzzle") or ""]
	table.insert(pieces, { Name = "Muzzle", Asset = if device then device.Asset else gun.Muzzle, At = barrel.Muzzle })
	for _, slot in { "Optic", "Grip" } do
		local acc = GunParts.Accessories[idOf(attachments, slot) or ""]
		if acc then
			table.insert(pieces, { Name = slot, Asset = acc.Asset, At = points[acc.At] })
		end
	end
	return pieces
end

-- Where the bore ends, from the gun's origin (the muzzle flash and the tracer start here).
function GunParts.MuzzleEnd(gunId, attachments)
	local barrel = GunParts.Barrel(gunId, attachments)
	return barrel and barrel.End
end

return GunParts
